mapper.select:


     and stake_round_id = #{stakeRoundId}
     and snapshot_time = #{snapshotTime}
     and user_id = #{userId}
     and account = #{account}
     and user_code = #{userCode}
     and avatar = #{avatar}
     and email = #{email}

     and game_level = #{gameLevel}
     and min_game_level = #{minGameLevel}

     and node_level = #{nodeLevel}
     and min_node_level = #{minNodeLevel}

     and layer_level = #{layerLevel}
     and min_layer_level = #{minLayerLevel}


        and GREATEST(node_level, min_node_level) = #{finaNodeLevel}



        and GREATEST(layer_level, min_layer_level) = #{finaLayerLevel}



        and GREATEST(game_level, min_game_level) = #{finaGameLevel}


     and invite_user_code = #{inviteUserCode}
     and invite_user_id = #{inviteUserId}
     and status = #{status}
     and is_valid = #{isValid}
     and sub_num = #{subNum}
     and valid_sub_num = #{validSubNum}
     and umbrella_num = #{umbrellaNum}
     and valid_umbrella_num = #{validUmbrellaNum}
     and performance = #{performance}
     and sub_mining = #{subMining}
     and performance_mining = #{performanceMining}
     and community_performance = #{communityPerformance}
     and sub_performance = #{subPerformance}
     and umbrella_performance = #{umbrellaPerformance}
     and parent_chain = #{parentChain}
     and create_time between #{params.beginCreateTime} and #{params.endCreateTime}
     and withdrawal_open_or_close = #{withdrawalOpenOrClose}
     and last_login_ip = #{lastLoginIp}
     and dividend_available_amount = #{dividendAvailableAmount}
     and distributed_amount = #{distributedAmount}
     and has_studio_subsidy_eligible = #{hasStudioSubsidyEligible}

